commands.cmd:
p=$(command -v pdftotext) || { echo "POPPLER_RESOLVE_FAIL: pdftotext not on PATH"; exit 1; }
rp=$(readlink -f "$p") || { echo "POPPLER_RESOLVE_FAIL: unresolvable $p"; exit 1; }
case "$rp" in "$HOME"/.local/share/codex-ecosystem/poppler-26.09.0/prefix/*) : ;; *) echo "POPPLER_RESOLVE_FAIL: unexpected path $rp"; exit 1 ;; esac
pins=$(python3 -c "import json,glob;c=[x for x in json.load(open('manifests/stack.json'))['components'] if x['id']=='poppler'][0];w=sorted({x['pin'] for f in glob.glob('catalogs/landscape/*.json') for l in json.load(open(f)).get('layers',[]) for x in (l.get('winners') or []) if x.get('component_id')=='poppler'});print('stack version',c['version'],'| winner pins',w);raise SystemExit(0 if c['version']=='26.09.0' and w==['26.09.0'] else 1)") || { echo "POPPLER_RESOLVE_FAIL: pin records disagree: $pins"; exit 1; }
if dpkg -s poppler-utils > /dev/null 2>&1; then echo "POPPLER_RESOLVE_FAIL: the apt package poppler-utils is installed"; exit 1; fi
echo "POPPLER_RESOLVE_OK | resolves: $p -> $rp (this host's poppler-26.09.0 source-build prefix) | $pins | dpkg -s poppler-utils: not installed"
